package fraymus.workspace;

import org.json.*;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import javax.imageio.ImageIO;
import java.util.*;

final class TrackingPresentation {
    static String verdict(JSONObject job){return job.getJSONObject("gate").getBoolean("passed")?"Candidate passed fixed gates":"Candidate rejected; active profile unchanged";}
    static JSONArray checks(JSONObject job){return new JSONArray().put(new JSONObject().put("selector","#verdict").put("expectText",verdict(job))).put(new JSONObject().put("selector","#comparison-id").put("expectText",job.getString("id"))).put(new JSONObject().put("selector",".sequence").put("expectCount",job.getJSONArray("results").length())).put(new JSONObject().put("selector",".profile").put("expectCount",2)).put(new JSONObject().put("selector",".overlap-chart").put("expectCount",job.getJSONArray("results").length())).put(new JSONObject().put("selector","#evaluation-frames").put("expectText",Integer.toString(job.getJSONObject("gate").getInt("scoredEvaluationFrames")))).put(new JSONObject().put("selector","#gain").put("expectText",number(job.getJSONObject("gate").getDouble("pooledMeanIouGain")))).put(new JSONObject().put("selector","#scope").put("expectText","Human-guided box tracking on declared sequences. Initialization excluded. No later reference enters the tracker. This is not general recognition or an official DAVIS segmentation score."));}
    static String number(double n){return String.format(Locale.ROOT,"%.4f",n);}
    private static String esc(String s){return SpatialReport.escape(s);}
    private static String thumbnail(byte[] bytes) throws Exception {var image=TrackingEvaluation.image(bytes,false);double scale=Math.min(1,320.0/Math.max(image.getWidth(),image.getHeight()));var out=new BufferedImage((int)(image.getWidth()*scale),(int)(image.getHeight()*scale),BufferedImage.TYPE_INT_RGB);var g=out.createGraphics();g.drawImage(image,0,0,out.getWidth(),out.getHeight(),null);g.dispose();var encoded=new ByteArrayOutputStream();ImageIO.write(out,"jpg",encoded);return Base64.getEncoder().encodeToString(encoded.toByteArray());}
    private static String csvCell(String text){if(text.matches("^[=+@-].*"))text="'"+text;return "\""+text.replace("\"","\"\"")+"\"";}
    static JSONObject report(JSONObject job,TrackingLab lab) throws Exception {if(!job.getString("status").equals("completed"))throw new IllegalStateException("A completed actual comparison is required");var html=new StringBuilder("""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tracking evaluation evidence</title><style>body{margin:0;background:#edf3ef;color:#173b35;font:16px/1.55 system-ui}main{max-width:1000px;margin:auto;padding:26px}section{padding:20px;border:1px solid #b9ccc1;border-radius:12px;background:white;margin:20px 0}h1{font-size:34px}pre,code{white-space:pre-wrap;overflow-wrap:anywhere}.profiles,.metrics{display:flex;gap:25px;flex-wrap:wrap}.metrics b{display:block;font-size:28px}.pictures{display:grid;grid-template-columns:1fr 1fr;gap:16px}img,svg{width:100%;height:auto}figure{margin:0}figcaption{font-size:13px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #bdcfc3}.scroll{overflow:auto}@media(max-width:550px){main{padding:16px}.pictures{grid-template-columns:1fr}h1{font-size:28px}}</style><main><p>FRAYNIX / EDITION 023 / RECORDED SEQUENCE EVALUATION</p>
        """);var gate=job.getJSONObject("gate");html.append("<h1 id='verdict'>").append(esc(verdict(job))).append("</h1><section class='metrics'><div><b id='evaluation-frames'>").append(gate.getInt("scoredEvaluationFrames")).append("</b>Scored evaluation frames</div><div><b id='gain'>").append(number(gate.getDouble("pooledMeanIouGain"))).append("</b>Mean overlap gain</div><div><b>").append(number(gate.getDouble("candidateIouHalfFraction"))).append("</b>Candidate fraction at IoU ≥0.5</div></section><p class='profiles'><span class='profile'>Amber: rgb-v1</span><span class='profile'>Green: adaptive-v2</span></p><p id='scope'>Human-guided box tracking on declared sequences. Initialization excluded. No later reference enters the tracker. This is not general recognition or an official DAVIS segmentation score.</p>");
        var sources=new JSONArray();var traceFiles=new JSONObject();var traceIndex=new JSONArray();int caseIndex=0;var csv=new StringBuilder("sequence,split,profile,source_frame,iou,state,processing_ms\n");for(Object raw:job.getJSONArray("results")){var result=(JSONObject)raw;var d=lab.readDataset(result.getString("datasetId"));sources.put(TrackingLab.datasetSummary(d));String sourceFile="dataset-"+caseIndex+".json";traceFiles.put(sourceFile,d.toString());var traceEntry=new JSONObject().put("datasetId",d.getString("id")).put("sourceFile",sourceFile);for(String profile:List.of(TrackingEvaluation.BASELINE,TrackingEvaluation.CANDIDATE)){String file="trace-"+caseIndex+"-"+profile+".json";traceFiles.put(file,result.getJSONObject(profile).toString());traceEntry.put(profile,file);}traceIndex.put(traceEntry);caseIndex++;var frames=d.getJSONArray("frames");int last=frames.length()-1;html.append("<section class='sequence'><h2>").append(esc(d.getString("title"))).append(" · ").append(esc(d.getString("split"))).append("</h2><p>Source content SHA-256 <code>").append(d.getString("contentSha256")).append("</code></p><div class='pictures'>");for(int ordinal:new int[]{0,last})html.append("<figure><img class='source-frame' alt='Actual original sequence frame thumbnail' src='data:image/jpeg;base64,").append(thumbnail(lab.image(d.getString("id"),ordinal))).append("'><figcaption>Original source frame ").append(frames.getJSONObject(ordinal).getInt("sourceFrame")).append(". Thumbnail, before annotation overlays.</figcaption></figure>");html.append("</div><h3>Overlap on every selected prediction frame</h3><svg class='overlap-chart' viewBox='0 0 720 250' role='img' aria-label='Reference overlap for both frozen profiles'><path d='M35 15V220H705' fill='none' stroke='#648478'/><path d='M35 115H705' stroke='#9eb6a9' stroke-dasharray='5 5'/>");int color=0;for(String profile:List.of(TrackingEvaluation.BASELINE,TrackingEvaluation.CANDIDATE)){var evaluation=result.getJSONObject(profile);var predictions=evaluation.getJSONArray("frames");var points=new StringBuilder();for(int i=0;i<predictions.length();i++){var f=predictions.getJSONObject(i);points.append(35+670.0*i/Math.max(1,predictions.length()-1)).append(',').append(215-200*f.getDouble("iou")).append(' ');csv.append(csvCell(d.getString("sequence"))).append(',').append(d.getString("split")).append(',').append(profile).append(',').append(f.getInt("sourceFrame")).append(',').append(f.getDouble("iou")).append(',').append(f.getJSONObject("prediction").getString("status")).append(',').append(f.getDouble("processingMillis")).append('\n');}html.append("<polyline class='actual-overlap' points='").append(points).append("' fill='none' stroke='").append(color++==0?"#d99b30":"#168961").append("' stroke-width='3'/>");}html.append("</svg><p>Horizontal axis: selected frame order, not seconds. Dashed line: IoU0.5. Lost predictions count as zero; no frame resets.</p><div class='scroll'><table><tr><th>Profile</th><th>Mean IoU</th><th>IoU≥0.5</th><th>Lost</th><th>Median / p95 ms</th></tr>");for(String profile:List.of(TrackingEvaluation.BASELINE,TrackingEvaluation.CANDIDATE)){var m=result.getJSONObject(profile).getJSONObject("metrics");html.append("<tr><td>").append(profile).append("</td><td>").append(number(m.getDouble("meanIou"))).append("</td><td>").append(number(m.getDouble("iouHalfFraction"))).append("</td><td>").append(m.getInt("lost")).append("</td><td>").append(number(m.getDouble("medianProcessingMillis"))).append(" / ").append(number(m.getDouble("p95ProcessingMillis"))).append("</td></tr>");}html.append("</table></div><p>Latency includes CPU image decode and tracking; browser capture, network, LLM and scoring are excluded.</p><p>").append(esc(d.getString("license"))).append(" · ").append(esc(d.getString("notes"))).append("</p></section>");}
        html.append("<section><h2>Reconstructed decision</h2><pre>").append(esc(gate.toString(2))).append("</pre><p>Comparison <code id='comparison-id'>").append(job.getString("id")).append("</code></p><details><summary>Frozen profile code identities</summary><pre>").append(esc(new JSONObject().put("outerClass",job.getJSONObject("profiles")).put("implementation",job.optJSONObject("implementations")).put("components",job.optJSONObject("implementationComponents")).toString(2))).append("</pre></details></section></main></html>");JSONObject protocol;try(var in=TrackingPresentation.class.getResourceAsStream("/perception/acceptance-023.json")){protocol=new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}var summary=new JSONObject(job.toString());summary.remove("results");summary.put("resultFiles",traceIndex);var files=new JSONObject().put("index.html",html.toString()).put("comparison.json",summary.toString(2)).put("datasets.json",sources.toString(2)).put("accuracy.csv",csv.toString()).put("verification.json",gate.toString(2)).put("protocol.json",protocol.toString(2));for(String name:traceFiles.keySet())files.put(name,traceFiles.getString(name));return new JSONObject().put("title","Tracking comparison · "+job.getString("id").substring(0,8)).put("files",files).put("sources",new JSONArray().put("tracking-comparison:"+job.getString("id")));
    }
    static String replay(JSONObject dataset){String info=new JSONObject().put("id",dataset.getString("id")).put("title",dataset.getString("title")).put("frames",dataset.getJSONArray("frames").length()).put("width",dataset.getInt("width")).put("height",dataset.getInt("height")).put("license",dataset.getString("license")).toString().replace("</","<\\/");return """
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recorded tracking sequence</title><style>body{font:15px/1.5 system-ui;margin:20px;background:#edf3ef;color:#173b35}button{padding:9px;margin:3px}canvas{display:block;width:100%;height:auto;background:#122b2e}small{display:block}p{overflow-wrap:anywhere}</style><h1 id="title">Recorded frame replay</h1><p>Actual recorded sequence frames. Playback interval1 second; original capture FPS unknown. No reference boxes are shown inside the source canvas.</p><button id="play">Play / pause</button><button id="next">Next frame</button><button id="reset">First frame</button><p id="position"></p><canvas aria-label="Recorded image pixels; inspect independently"></canvas><small id="credit"></small><script>
        """+"const source="+info+";"+"""
        const canvas=document.querySelector('canvas'),c=canvas.getContext('2d');canvas.width=source.width;canvas.height=source.height;document.querySelector('#title').textContent=source.title;document.querySelector('#credit').textContent=source.license;let frame=0,timer=null,busy=false;
        async function show(index){if(busy)return;busy=true;try{const image=new Image();image.src='/tracking-assets/'+source.id+'/'+index;await image.decode();c.drawImage(image,0,0,canvas.width,canvas.height);frame=index;document.querySelector('#position').textContent='Selected frame '+(frame+1)+' / '+source.frames;}finally{busy=false;}}
        function stop(){clearInterval(timer);timer=null;}document.querySelector('#next').onclick=()=>{stop();show(Math.min(source.frames-1,frame+1));};document.querySelector('#reset').onclick=()=>{stop();show(0);};document.querySelector('#play').onclick=()=>{if(timer){stop();return;}timer=setInterval(()=>{if(frame>=source.frames-1){stop();return;}show(frame+1);},1000);};window.trackingReplay={show,source,get frame(){return frame;}};show(0);
        </script></html>
        """;}
}
